
.card {
  width: 100%;
  max-width: 480px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 16px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 12px;
  box-shadow: 0 4px 16px rgba(184, 128, 92, 0.10);
}

.header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  padding: 14px 16px;
  background: linear-gradient(135deg, #fdf6ee, #f9ecdf);
  border-bottom: 1px solid var(--c-border);
}

.title-wrap {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.title {
  font-size: 17px;
  font-weight: 700;
  color: var(--c-primary-deep);
  letter-spacing: 4px;
}

.subtitle {
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 1px;
}

.status {
  font-size: 11px;
  color: var(--c-primary-deep);
  background: #fff;
  border: 1px solid var(--c-border);
  border-radius: 999px;
  padding: 3px 10px;
}

.body {
  padding: 14px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.stage-chip {
  align-self: flex-start;
  font-size: 11px;
  color: var(--c-primary-deep);
  background: #fdf3ea;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 3px 8px;
}

.bar-block {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.bar-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
}

.bar-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
  letter-spacing: 1px;
}

.bar-pct {
  font-size: 11px;
  font-weight: 700;
  color: var(--c-text-muted);
}

.track {
  height: 12px;
  border-radius: 999px;
  background: #f2e9df;
  overflow: hidden;
}

.fill {
  height: 100%;
  border-radius: 999px;
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}

.fill-primary {
  background: linear-gradient(90deg, #f0c9a0, var(--c-primary));
}

.fill-danger {
  background: linear-gradient(90deg, #eec3b8, var(--c-danger));
}

.fill-accent {
  background: linear-gradient(90deg, #e3cfae, var(--c-accent));
}

.bar-note {
  font-size: 11px;
  color: var(--c-text-muted);
}

.trace-block {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-top: 4px;
  border-top: 1px dashed var(--c-border);
}

.trace-head {
  font-size: 11px;
  font-weight: 600;
  color: var(--c-primary-deep);
  letter-spacing: 1px;
}

.trace-item {
  font-size: 11px;
  color: var(--c-text-muted);
}
